use actix_web::{
    body::MessageBody,
    dev::{ServiceRequest, ServiceResponse},
    error::ErrorUnauthorized,
    middleware::Next,
    Error,
};

pub async fn require_api_key(
    req: ServiceRequest,
    next: Next<impl MessageBody>,
