    let expected = std::env::var("ARTICLES_API_KEY").unwrap_or_default();
    let given = req
        .headers()
        .get("Authorization")
        .and_then(|v| v.to_str().ok())
        .and_then(|v| v.strip_prefix("Bearer "));

    match given {
        Some(key) if !expected.is_empty() && key == expected => next.call(req).await,
